export type State = v.InferOutput<typeof StateSchema>;
export interface GetAuthURLResult {
    url: string;
    sealedState: string;
}
export interface GetAuthURLOptions {
    screenHint?: 'sign-up' | 'sign-in';
    returnPathname?: string;
    organizationId?: string;
    redirectUri?: string;
    loginHint?: string;
    prompt?: 'consent';
    state?: string;
