    enabled: boolean;
    unauthenticatedPaths: string[];
}
export interface AuthkitMiddlewareOptions {
    debug?: boolean;
    middlewareAuth?: AuthkitMiddlewareAuth;
    redirectUri?: string;
    signUpPaths?: string[];
    eagerAuth?: boolean;
