import { withAuth } from "@workos-inc/authkit-nextjs";
import type { User as WorkOSUser } from "@workos-inc/node";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

// Mock teammates shown on the dashboard alongside the signed-in user.
const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

function toUser(workosUser: WorkOSUser): User {
  const name =
    workosUser.name ??
    [workosUser.firstName, workosUser.lastName].filter(Boolean).join(" ") ||
    workosUser.email;

  return {
    id: workosUser.id,
    email: workosUser.email,
    name,
    createdAt: workosUser.createdAt,
  };
}

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// Reads the real signed-in user from the WorkOS session. Returns undefined
// when nobody is signed in — callers that require auth (e.g. /dashboard)
// should use `requireCurrentUser` instead.
export async function getCurrentUser(): Promise<User | undefined> {
  const { user } = await withAuth();
  return user ? toUser(user) : undefined;
}

// Same as `getCurrentUser`, but redirects signed-out visitors into the
// AuthKit sign-in flow instead of returning undefined. Use this at the top
// of any page that must be behind auth.
export async function requireCurrentUser(): Promise<User> {
  const { user } = await withAuth({ ensureSignedIn: true });
  return toUser(user);
}

